import math
def run(n, bias_deg):
    x = y = th = 0.0
    for _ in range(n):
        th += math.radians(bias_deg)
        x += 0.1*math.cos(th); y += 0.1*math.sin(th)
    return math.hypot(x - n*0.1, y)
for n in (100, 500, 1000):
    e = run(n, 0.05); L = n*0.1
    print(f"{L:5.0f} m 주행: 오차 {e:6.2f} m ({100*e/L:.1f}%)")
#    10 m 주행: 오차   0.44 m (4.4%)
#    50 m 주행: 오차  10.87 m (21.7%)
#   100 m 주행: 오차  42.76 m (42.8%)
